import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"PlaceholderAPI 占位符","description":"","frontmatter":{},"headers":[],"relativePath":"modules/storage/placeholders.md","filePath":"modules/storage/placeholders.md","lastUpdated":0}`),a={name:`modules/storage/placeholders.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="placeholderapi-占位符" tabindex="-1">PlaceholderAPI 占位符 <a class="header-anchor" href="#placeholderapi-占位符" aria-label="Permalink to “PlaceholderAPI 占位符”">​</a></h1><p>EmakiStorage 注册到 PlaceholderAPI 的占位符及其计算口径如下, 可直接复制到计分板, 菜单等模板中使用</p><p>前置条件: 已安装 PlaceholderAPI. 满足后 EmakiStorage 注册扩展, 标识符为 <code>emakistorage</code>. 这些占位符可以用在计分板, 菜单, 聊天格式, BossBar, ActionBar 以及支持 PlaceholderAPI 的其他插件文本模板里</p><p>PlaceholderAPI 未安装时, EmakiStorage 本体仍然可以正常运行, 只是不会注册 <code>%emakistorage_*%</code> 这些外部占位符</p><h2 id="占位符列表" tabindex="-1">占位符列表 <a class="header-anchor" href="#占位符列表" aria-label="Permalink to “占位符列表”">​</a></h2><table tabindex="0"><thead><tr><th>占位符</th><th>说明</th></tr></thead><tbody><tr><td><code>%emakistorage_used_slots%</code></td><td>已经占用的槽位数量</td></tr><tr><td><code>%emakistorage_total_slots%</code></td><td>有效槽位的总数</td></tr><tr><td><code>%emakistorage_free_slots%</code></td><td>还空着多少槽位</td></tr><tr><td><code>%emakistorage_purchased_slots%</code></td><td>已经购买了多少槽位</td></tr><tr><td><code>%emakistorage_granted_slots%</code></td><td>授予了多少槽位</td></tr><tr><td><code>%emakistorage_pages%</code></td><td>总共多少页</td></tr><tr><td><code>%emakistorage_stack_limit%</code></td><td>当前生效的玩家级单槽上限</td></tr><tr><td><code>%emakistorage_sort_mode%</code></td><td>当前排序模式的 id</td></tr><tr><td><code>%emakistorage_total_amount%</code></td><td>所有条目数量加在一起的总和, 溢出时停在上限 <code>Long.MAX_VALUE</code></td></tr><tr><td><code>%emakistorage_count_&lt;token&gt;%</code></td><td>指定 ItemSource token 的库存量, 没有这条条目时为 <code>0</code></td></tr></tbody></table><h2 id="求值线程与未载入数据" tabindex="-1">求值线程与未载入数据 <a class="header-anchor" href="#求值线程与未载入数据" aria-label="Permalink to “求值线程与未载入数据”">​</a></h2><p>线程约束: 所有占位符读的都是在线玩家在内存里的数据, 不会去读磁盘, PlaceholderAPI 在哪个线程调用就在哪个线程上计算, 因为这种地方不能做会让线程卡住的磁盘读写. 异常处理: 玩家数据还没载入时返回 <code>0</code>, 认不出来的占位符返回空字符串</p><p>匹配规则: 占位符名不区分大小写, 计算前统一转成小写, 所以 <code>%emakistorage_USED_SLOTS%</code> 和全小写是一样的. <code>count_</code> 前缀会先于其他名字去匹配, 它后面的部分按 CoreLib ItemSource token 解析 (同样先转小写), 解析不出来的 token 返回 <code>0</code>. 所有结果都按十进制字符串返回, 整数不加千分位分隔</p><p>异常处理: 玩家参数为空时 (比如在控制台里, 或者求值时没有玩家上下文) 返回空字符串, 而不是 <code>0</code></p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to “相关页面”">​</a></h2><ul><li><a href="./capacity.html">容量与缩容</a>: <code>total_slots</code>, <code>purchased_slots</code> 等数值背后的四来源容量模型</li><li><a href="./events.html">事件 API</a>: 需要拦截而不只是读取时使用的 Bukkit 事件</li><li><a href="./api.html">API 与集成</a>: 在代码中读取容量与存量的方式</li></ul>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};